#!/bin/bash
set -e

cd Dependencies/jpeg-turbo

rm src/jconfig.h
rm src/jconfigint.h
rm src/jversion.h

$CMAKE_COMMAND . $CMAKE_OPTIONS  $JPEGTURBO_OPTIONS -DCMAKE_INSTALL_PREFIX=$INSTALL_PREFIX -DWITH_SYSTEM_ZLIB=ON -DZLIB_INCLUDE_DIR=$INSTALL_PREFIX/include -DZLIB_LIBRARY=$INSTALL_PREFIX/lib/libz.a -DENABLE_SHARED=false -DCMAKE_BUILD_TYPE=$CMAKE_BUILD_TYPE -DCMAKE_C_FLAGS="$FLAGS"
$MAKE install
